import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BusinessInfographicProps = Record<string, any>;

const Bar = ({
  value,
  label,
  color,
  delay,
  fps,
  frame,
  textColor,
  trackWidth,
  trackMaxHeight,
  valueFontSize,
  labelFontSize
}: {
  value: number;
  label: string;
  color: string;
  delay: number;
  fps: number;
  frame: number;
  textColor: string;
  trackWidth: number;
  trackMaxHeight: number;
  valueFontSize: number;
  labelFontSize: number;
}) => {
  const barProgress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 16, stiffness: 120, mass: 0.8 }
  });

  const barHeight = Math.min(trackMaxHeight, Math.max(0, barProgress * (value / 100) * trackMaxHeight));
  const displayValue = Math.min(value, Math.max(0, Math.round(barProgress * value)));
  const borderRadius = trackWidth * 0.1;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: trackWidth * 1.6 }}>
      {/* Chart Track Container */}
      <div style={{ height: trackMaxHeight, width: trackWidth, position: 'relative' }}>
        <div style={{ position: 'absolute', bottom: 0, left: 0, right: 0, height: '100%', backgroundColor: '#f1f5f9', borderRadius }} />
        <div style={{
          position: 'absolute',
          bottom: 0, left: 0, right: 0,
          height: barHeight,
          backgroundColor: color,
          borderRadius,
          boxShadow: '0 8px 25px -5px rgba(0,0,0,0.1)',
          transition: "none"
        }} />

        {/* Value Label Above Bar */}
        <div style={{
          position: 'absolute',
          bottom: barHeight + trackMaxHeight * 0.03,
          left: -trackWidth * 0.5,
          right: -trackWidth * 0.5,
          textAlign: 'center',
          opacity: interpolate(barProgress, [0.1, 0.4], [0, 1], { extrapolateRight: 'clamp', extrapolateLeft: 'clamp' }),
          transition: "none"
        }}>
          <span style={{ fontSize: valueFontSize, fontWeight: 800, color: textColor, transition: "none" }}>{displayValue}%</span>
        </div>
      </div>

      {/* Label Below Chart */}
      <div style={{
        marginTop: trackMaxHeight * 0.08,
        fontSize: labelFontSize,
        fontWeight: 600,
        color: textColor,
        textAlign: 'center',
        lineHeight: 1.3,
        opacity: interpolate(barProgress, [0.3, 0.7], [0, 1], { extrapolateRight: 'clamp', extrapolateLeft: 'clamp' }),
        transform: `translateY(${interpolate(barProgress, [0.3, 0.7], [trackMaxHeight * 0.05, 0], { extrapolateRight: 'clamp', extrapolateLeft: 'clamp' })}px)`,
        transition: "none"
      }}>
        {label}
      </div>
    </div>
  );
};

const BusinessInfographic: React.FC<BusinessInfographicProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 10,
  textColor = "#1e293b",
  leftTitle = "Internet Leads",
  leftTimeValue = 80,
  leftTimeLabel = "Time & Effort",
  leftTimeColor = "#ea580c",
  leftConvValue = 4,
  leftConvLabel = "Conversion",
  leftConvColor = "#dc2626",
  leftNoteText = "30% Commission Taken",
  leftNoteColor = "#dc2626",
  rightTitle = "Referral Leads",
  rightTimeValue = 20,
  rightTimeLabel = "Time & Effort",
  rightTimeColor = "#2563eb",
  rightConvValue = 65,
  rightConvLabel = "Conversion",
  rightConvColor = "#16a34a",
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Open Sauce"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgStyle = transparentBackground ? "transparent" : backgroundColor;

  // Responsive Math
  const s = Math.min(width, height);
  const pagePadding = s * 0.08;
  const gapBetweenCols = width * 0.05;
  const gapBetweenBars = width * 0.05;

  const titleFontSize = s * 0.055;
  const trackWidth = width * 0.07;
  const trackMaxHeight = height * 0.52;
  const valueFontSize = s * 0.038;
  const labelFontSize = s * 0.028;

  // Global Animations
  const titleSpring = spring({ frame: frame - 10, fps, config: { damping: 16, stiffness: 120 } });
  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const titleY = interpolate(titleSpring, [0, 1], [height * 0.05, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const dividerSpring = spring({ frame: frame - 15, fps, config: { damping: 16, stiffness: 120 } });
  const dividerScale = interpolate(dividerSpring, [0, 1], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const dividerOpacity = Math.min(1, Math.max(0, dividerScale));

  const noteSpring = spring({ frame: frame - 80, fps, config: { damping: 16, stiffness: 120 } });
  const noteOpacity = interpolate(noteSpring, [0, 1], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const noteY = interpolate(noteSpring, [0, 1], [height * 0.02, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  return (
    <AbsoluteFill style={{
      backgroundColor: bgStyle,
      fontFamily: "Open Sauce",
      color: textColor,
      padding: `${pagePadding}px ${pagePadding * 1.5}px`,
      transition: "none"
    }}>
      <div style={{ display: 'flex', flexDirection: 'row', width: '100%', height: '100%', gap: gapBetweenCols, transition: "none" }}>

        {/* Left Column */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', transition: "none" }}>
          <div style={{ height: height * 0.15, display: 'flex', alignItems: 'center', justifyContent: 'center', transition: "none" }}>
            <h2 style={{
              fontSize: titleFontSize,
              fontWeight: 800,
              color: textColor,
              margin: 0,
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              transition: "none",
              textAlign: "center"
            }}>
              {leftTitle}
            </h2>
          </div>

          <div style={{ flex: 1, display: 'flex', flexDirection: 'row', alignItems: 'flex-end', justifyContent: 'center', gap: gapBetweenBars, transition: "none" }}>
            <Bar
              value={leftTimeValue} label={leftTimeLabel} color={leftTimeColor} delay={30} fps={fps} frame={frame} textColor={textColor}
              trackWidth={trackWidth} trackMaxHeight={trackMaxHeight} valueFontSize={valueFontSize} labelFontSize={labelFontSize}
            />
            <Bar
              value={leftConvValue} label={leftConvLabel} color={leftConvColor} delay={60} fps={fps} frame={frame} textColor={textColor}
              trackWidth={trackWidth} trackMaxHeight={trackMaxHeight} valueFontSize={valueFontSize} labelFontSize={labelFontSize}
            />
          </div>

          <div style={{ height: height * 0.1, display: 'flex', alignItems: 'center', justifyContent: 'center', transition: "none" }}>
            <div style={{
              opacity: noteOpacity,
              transform: `translateY(${noteY}px)`,
              backgroundColor: leftNoteColor + '15', // light background tint
              padding: `${s * 0.01}px ${s * 0.02}px`,
              borderRadius: s * 0.01,
              transition: "none"
            }}>
              <span style={{
                fontSize: labelFontSize * 1.1,
                fontWeight: 700,
                color: leftNoteColor,
                transition: "none"
              }}>
                {leftNoteText}
              </span>
            </div>
          </div>
        </div>

        {/* Divider */}
        <div style={{
          width: 2,
          height: '75%',
          alignSelf: 'center',
          backgroundColor: '#e2e8f0',
          transform: `scaleY(${dividerScale})`,
          opacity: dividerOpacity,
          transformOrigin: 'center',
          transition: "none"
        }} />

        {/* Right Column */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', transition: "none" }}>
          <div style={{ height: height * 0.15, display: 'flex', alignItems: 'center', justifyContent: 'center', transition: "none" }}>
            <h2 style={{
              fontSize: titleFontSize,
              fontWeight: 800,
              color: textColor,
              margin: 0,
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              transition: "none",
              textAlign: "center"
            }}>
              {rightTitle}
            </h2>
          </div>

          <div style={{ flex: 1, display: 'flex', flexDirection: 'row', alignItems: 'flex-end', justifyContent: 'center', gap: gapBetweenBars, transition: "none" }}>
            <Bar
              value={rightTimeValue} label={rightTimeLabel} color={rightTimeColor} delay={30} fps={fps} frame={frame} textColor={textColor}
              trackWidth={trackWidth} trackMaxHeight={trackMaxHeight} valueFontSize={valueFontSize} labelFontSize={labelFontSize}
            />
            <Bar
              value={rightConvValue} label={rightConvLabel} color={rightConvColor} delay={60} fps={fps} frame={frame} textColor={textColor}
              trackWidth={trackWidth} trackMaxHeight={trackMaxHeight} valueFontSize={valueFontSize} labelFontSize={labelFontSize}
            />
          </div>

          {/* Empty footer to balance the left column note */}
          <div style={{ height: height * 0.1, transition: "none" }} />
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default BusinessInfographic;